mapper.select:
select

from profile_meta_datasource_type
where 1 = 1

  and status = #{status,jdbcType=INTEGER}


  and datasource_type_id = #{dataSourceTypeId,jdbcType=INTEGER}


  and datasource_type_name = #{dataSourceTypeName,jdbcType=VARCHAR}


  and source_type = #{sourceType,jdbcType=INTEGER}


  and creator = #{creator,jdbcType=VARCHAR}


  and modifier = #{modifier,jdbcType=VARCHAR}
